    question: '[Exercises 1.3–1.5 & Rev 1] (a) Given that $y$ varies directly as the square of $x$ ($y \\propto x^2$) and $y = 45$ when $x = 3$, find $y$ when $x = 5$. (b) If $12$ tailors sew school uniforms in $10$ days, how many tailors working at the same rate are required to finish the uniforms in $6$ days? (c) $P$ varies directly as $Q$ and inversely as the square root of $R$ ($P = \\frac{kQ}{\\sqrt{R}}$); if $P = 18$ when $Q = 6$ and $R = 4$, find $P$ when $Q = 10$ and $R = 9$.',
