    question: '[Exercise 1.6 Q1, Q5 & Exercise 1.7 Q5, Q11, Q12] (a) State the domain and range of the relation $R = \\{(x, y) : y = x^2 + 3\\}$. (b) Find the inverse relation $R^{-1}$ of $R = \\{(x, y) : y = 2x + 1\\}$. (c) Find the inverse $R^{-1}$, domain of $R^{-1}$, and range of $R^{-1}$ for $R = \\{(x, y) : y = \\frac{2}{x + 5}\\}$. (d) Find the inverse of $R = \\{(x, y) : y = 3x^2 - 1\\}$ and state the domain of $R^{-1}$.',
