      '(a) Domain $= \\mathbb{R}$, Range $= \\{y \\in \\mathbb{R} : y \\ge 3\\}$ ; (b) $R^{-1} = \\{(x, y) : y = \\frac{1}{2}x - \\frac{1}{2}\\}$ ; (c) $R^{-1}: y = \\frac{2}{x} - 5$ (Domain $x \\ne 0$, Range $y \\ne -5$) ; (d) $R^{-1}: y = \\pm\\sqrt{\\frac{x + 1}{3}}$ (Domain $x \\ge -1$)',
      '(a) Domain $= \\{x \\ge 3\\}$, Range $= \\mathbb{R}$ ; (b) $R^{-1} = \\{(x, y) : y = 2x - 1\\}$ ; (c) $R^{-1}: y = \\frac{2}{x - 5}$ ; (d) $R^{-1}: y = \\sqrt{\\frac{x - 1}{3}}$ (Domain $x \\ge 1$)',
