  // 5. FORM 3 ADDITIONAL MATHEMATICS — ALL 6 CHAPTERS (16 distinct items/chapter)
  // =========================================================================
  pushDistinctChapterBank('addmath-f3-bank-ch1', 'Form 3', 'Additional Mathematics', 'Chapter 1: Sets', ADD_MATH_F3_BOOK, [
    ['Distributive law of sets', 'Exercise 1.1 Q2 (Page 4)', 'Given $A = \\{1, 2, 3, 4\\}$, $B = \\{3, 4, 5, 6\\}$, and $C = \\{2, 4, 6, 8\\}$, find $A \\cap (B \\cup C)$ and verify $A \\cap (B \\cup C) = (A \\cap B) \\cup (A \\cap C)$:', '$\\{2, 3, 4\\}$', '$\\{3, 4\\}$', '$\\{1, 2, 3, 4, 5, 6, 8\\}$', '$\\{4\\}$'],
    ['Simplifying set difference complement', 'Exercise 1.2 Q3 (Page 8)', 'Using the laws of algebra of sets, simplify the expression $(B - A)\'$:', '$A \\cup B\'$', '$A \\cap B\'$', '$A\' \\cup B$', '$B - A\'$', '$(B - A)\' = (B \\cap A\')\' = B\' \\cup (A\')\' = A \\cup B\'$.'],
    ['Distributive and complement simplification', 'Exercise 1.2 Q5 (Page 9)', 'Simplify the set expression $(B \\cap C) \\cup (B \\cap C\')$ using set properties:', '$B$', '$C$', '$B \\cap C$', '$U$', '$B \\cap (C \\cup C\') = B \\cap U = B$.'],
    ['Simplifying intersection with complement', 'Exercise 1.2 Q7 (Page 9)', 'Use set identities to simplify $(A \\cup B) \\cap (A \\cup B\')$:', '$A$', '$B$', '$A \\cup B$', '$\\varnothing$', 'By distributivity, $A \\cup (B \\cap B\') = A \\cup \\varnothing = A$.'],
    ['Absorption law simplification', 'Exercise 1.2 Q9 (Page 9)', 'Simplify the set expression $X \\cup (X\' \\cap Y)$:', '$X \\cup Y$', '$X \\cap Y$', '$X$', '$Y$', 'By distributivity, $(X \\cup X\') \\cap (X \\cup Y) = U \\cap (X \\cup Y) = X \\cup Y$.'],
    ['Symmetric difference of sets', 'Exercise 1.1 Q6 (Page 5)', 'For sets $P = \\{a, b, c, d\\}$ and $Q = \\{c, d, e, f\\}$, find the symmetric difference $P \\Delta Q = (P - Q) \\cup (Q - P)$:', '$\\{a, b, e, f\\}$', '$\\{c, d\\}$', '$\\{a, b, c, d, e, f\\}$', '$\\{a, b\\}$'],
    ['Double difference simplification', 'Exercise 1.2 Q10 (Page 10)', 'Simplify the set expression $A - (A - B)$ using set algebra:', '$A \\cap B$', '$A - B$', '$B$', '$A \\cup B$', '$A \\cap (A \\cap B\')\' = A \\cap (A\' \\cup B) = (A \\cap A\') \\cup (A \\cap B) = A \\cap B$.'],
    ['Three-set inclusion-exclusion cardinality', 'Exercise 1.3 Q2 (Page 12)', 'Given $n(A) = 25$, $n(B) = 22$, $n(C) = 18$, $n(A \\cap B) = 10$, $n(B \\cap C) = 8$, $n(A \\cap C) = 7$, and $n(A \\cap B \\cap C) = 4$, find $n(A \\cup B \\cup C)$:', '$44$', '$40$', '$36$', '$48$', '$25 + 22 + 18 - 10 - 8 - 7 + 4 = 44$.'],
    ['Exactly one of three sets in a survey', 'Exercise 1.3 Q5 (Page 13)', 'In a Form 3 science stream: $30$ take Physics ($P$), $28$ take Chemistry ($C$), $26$ take Biology ($B$), $14$ take $P\\cap C$, $12$ take $C\\cap B$, $11$ take $P\\cap B$, and $7$ take all three. How many students take **Physics only**?', '$12$ students', '$5$ students', '$16$ students', '$9$ students', '$n(P \\text{ only}) = 30 - (14 - 7) - (11 - 7) - 7 = 30 - 7 - 4 - 7 = 12$ students.'],
    ['De Morgan law for three sets', 'Exercise 1.2 Q11 (Page 10)', 'By De Morgan\'s law, the complement of the union of three sets $(A \\cup B \\cup C)\'$ is identical to:', '$A\' \\cap B\' \\cap C\'$', '$A\' \\cup B\' \\cup C\'$', '$(A \\cap B \\cap C)\'$', '$A \\cap B\' \\cap C\'$'],
    ['Real interval union and intersection', 'Exercise 1.1 Q8 (Page 5)', 'Given real intervals $A = [-3, 4)$ and $B = (1, 7]$, find $A \\cap B$ and $A \\cup B$:', '$A \\cap B = (1, 4)$ and $A \\cup B = [-3, 7]$', '$A \\cap B = [1, 4]$ and $A \\cup B = (-3, 7)$', '$A \\cap B = [-3, 1]$ and $A \\cup B = (4, 7]$', '$A \\cap B = (1, 4]$ and $A \\cup B = [-3, 7)$'],
    ['Complement of interval in R', 'Exercise 1.1 Q10 (Page 6)', 'If the universal set is $\\mathbb{R}$ and $M = \\{x \\in \\mathbb{R} : -1 \\le x < 5\\}$, state the complement $M\'$:', '$\\{x \\in \\mathbb{R} : x < -1 \\text{ or } x \\ge 5\\}$', '$\\{x \\in \\mathbb{R} : x \\le -1 \\text{ or } x > 5\\}$', '$\\{x \\in \\mathbb{R} : -5 < x \\le 1\\}$', '$\\{x \\in \\mathbb{R} : x > 5\\}$'],
    ['Condition for $A \\cup B = A$', 'Revision Exercise 1 Q3 (Page 14)', 'For any two sets $A$ and $B$, if $A \\cup B = A$, what is the relationship between $A$ and $B$, and what is $A \\cap B$?', '$B \\subseteq A$ and $A \\cap B = B$', '$A \\subseteq B$ and $A \\cap B = A$', '$A \\cap B = \\varnothing$', '$A = B\'$'],
    ['Simplifying $(A \\cap B\') \\cup (A \\cap B)$', 'Revision Exercise 1 Q5 (Page 14)', 'Prove/simplify $(A \\cap B\') \\cup (A \\cap B) \\cup (A\' \\cap B)$ using set laws:', '$A \\cup B$', '$A \\cap B$', '$A$', '$B$', 'First two terms give $A \\cap (B\' \\cup B) = A$, and $A \\cup (A\' \\cap B) = A \\cup B$.'],
    ['Finding $n(A \\cap B \\cap C)$ from total', 'Revision Exercise 1 Q8 (Page 15)', 'In a survey of $100$ students, all study at least one of English ($E$), Kiswahili ($K$), or French ($F$). Given $n(E)=65$, $n(K)=55$, $n(F)=40$, $n(E\\cap K)=30$, $n(K\\cap F)=20$, and $n(E\\cap F)=25$, find $n(E \\cap K \\cap F)$:', '$15$', '$10$', '$20$', '$5$', '$100 = 65 + 55 + 40 - 30 - 20 - 25 + x \\Rightarrow 100 = 85 + x \\Rightarrow x = 15$.'],
    ['Power set of set difference', 'Revision Exercise 1 Q10 (Page 15)', 'Given $A = \\{1, 2, 3, 4, 5, 6\\}$ and $B = \\{2, 4, 6, 8\\}$, find $n(A - B)$ and the number of subsets of $(A - B)$:', '$n(A - B) = 3$ and $8$ subsets', '$n(A - B) = 4$ and $16$ subsets', '$n(A - B) = 3$ and $6$ subsets', '$n(A - B) = 2$ and $4$ subsets', '$A - B = \\{1, 3, 5\\}$ has $3$ elements, so it has $2^3 = 8$ subsets.'],
  ]);

  pushDistinctChapterBank('addmath-f3-bank-ch2', 'Form 3', 'Additional Mathematics', 'Chapter 2: Equation and remainder theorem', ADD_MATH_F3_BOOK, [
    ['Sum and product of quadratic roots', 'Exercise 2.1 Q1 (Page 19)', 'If $\\alpha$ and $\\beta$ are the roots of $2x^2 - 7x + 6 = 0$, find $\\alpha + \\beta$, $\\alpha\\beta$, and $\\frac{1}{\\alpha} + \\frac{1}{\\beta}$:', '$\\alpha + \\beta = \\frac{7}{2},\\; \\alpha\\beta = 3,\\; \\frac{1}{\\alpha} + \\frac{1}{\\beta} = \\frac{7}{6}$', '$\\alpha + \\beta = -\\frac{7}{2},\\; \\alpha\\beta = 3,\\; \\frac{1}{\\alpha} + \\frac{1}{\\beta} = -\\frac{7}{6}$', '$\\alpha + \\beta = 7,\\; \\alpha\\beta = 6,\\; \\frac{1}{\\alpha} + \\frac{1}{\\beta} = \\frac{7}{6}$', '$\\alpha + \\beta = \\frac{7}{2},\\; \\alpha\\beta = -3,\\; \\frac{1}{\\alpha} + \\frac{1}{\\beta} = \\frac{6}{7}$'],
    ['Sum of squares of roots', 'Exercise 2.1 Q3 (Page 19)', 'If $\\alpha$ and $\\beta$ are the roots of $x^2 - 5x + 3 = 0$, evaluate $\\alpha^2 + \\beta^2$ and $(\\alpha - \\beta)^2$:', '$\\alpha^2 + \\beta^2 = 19$ and $(\\alpha - \\beta)^2 = 13$', '$\\alpha^2 + \\beta^2 = 25$ and $(\\alpha - \\beta)^2 = 19$', '$\\alpha^2 + \\beta^2 = 19$ and $(\\alpha - \\beta)^2 = 22$', '$\\alpha^2 + \\beta^2 = 31$ and $(\\alpha - \\beta)^2 = 13$'],
    ['Sum of cubes of roots', 'Exercise 2.1 Q5 (Page 20)', 'Given that $\\alpha$ and $\\beta$ are the roots of $x^2 - 4x + 2 = 0$, find the value of $\\alpha^3 + \\beta^3$ using $\\alpha^3 + \\beta^3 = (\\alpha + \\beta)^3 - 3\\alpha\\beta(\\alpha + \\beta)$:', '$40$', '$64$', '$56$', '$32$', '$4^3 - 3(2)(4) = 64 - 24 = 40$.'],
    ['Forming quadratic with roots alpha^2 and beta^2', 'Exercise 2.1 Q7 (Page 20)', 'If $\\alpha$ and $\\beta$ are the roots of $x^2 - 6x + 4 = 0$, form the quadratic equation whose roots are $\\alpha^2$ and $\\beta^2$:', '$x^2 - 28x + 16 = 0$', '$x^2 - 36x + 16 = 0$', '$x^2 + 28x + 16 = 0$', '$x^2 - 28x + 8 = 0$', '$\\alpha^2 + \\beta^2 = 6^2 - 2(4) = 28$ and $\\alpha^2\\beta^2 = 16 \\Rightarrow x^2 - 28x + 16 = 0$.'],
    ['Forming quadratic with reciprocal roots', 'Exercise 2.1 Q9 (Page 21)', 'If $\\alpha$ and $\\beta$ are the roots of $3x^2 - 5x + 4 = 0$, find the quadratic equation with integer coefficients whose roots are $\\frac{1}{\\alpha}$ and $\\frac{1}{\\beta}$:', '$4x^2 - 5x + 3 = 0$', '$3x^2 + 5x + 4 = 0$', '$4x^2 + 5x + 3 = 0$', '$5x^2 - 4x + 3 = 0$'],
    ['Roots of a cubic polynomial', 'Exercise 2.1 Q11 (Page 21)', 'If $\\alpha, \\beta, \\gamma$ are the roots of the cubic equation $2x^3 - 6x^2 + 10x - 8 = 0$, find $\\alpha + \\beta + \\gamma$, $\\alpha\\beta + \\beta\\gamma + \\gamma\\alpha$, and $\\alpha\\beta\\gamma$:', '$\\sum\\alpha = 3,\\; \\sum\\alpha\\beta = 5,\\; \\alpha\\beta\\gamma = 4$', '$\\sum\\alpha = -3,\\; \\sum\\alpha\\beta = 5,\\; \\alpha\\beta\\gamma = -4$', '$\\sum\\alpha = 6,\\; \\sum\\alpha\\beta = 10,\\; \\alpha\\beta\\gamma = 8$', '$\\sum\\alpha = 3,\\; \\sum\\alpha\\beta = -5,\\; \\alpha\\beta\\gamma = 4$'],
    ['Remainder Theorem direct evaluation', 'Exercise 2.2 Q2 (Page 25)', 'Use the Remainder Theorem to find the remainder when $P(x) = 2x^3 - 5x^2 + 3x - 7$ is divided by $x - 2$:', '$-5$', '$3$', '$-9$', '$1$', '$P(2) = 2(8) - 5(4) + 3(2) - 7 = 16 - 20 + 6 - 7 = -5$.'],
    ['Remainder when divided by 2x + 1', 'Exercise 2.2 Q5 (Page 26)', 'Find the remainder when $f(x) = 4x^3 + 4x^2 - x + 3$ is divided by $2x + 1$:', '$4$', '$2$', '$3$', '$5$', '$f(-\\frac{1}{2}) = 4(-\\frac{1}{8}) + 4(\\frac{1}{4}) - (-\\frac{1}{2}) + 3 = -\\frac{1}{2} + 1 + \\frac{1}{2} + 3 = 4$.'],
    ['Finding unknown coefficient from remainder', 'Exercise 2.2 Q8 (Page 26)', 'When the polynomial $x^3 + kx^2 - 4x + 6$ is divided by $x - 3$, the remainder is $21$. Find the value of the constant $k$:', '$k = 0$', '$k = 2$', '$k = -1$', '$k = 3$', '$P(3) = 27 + 9k - 12 + 6 = 21 \\Rightarrow 21 + 9k = 21 \\Rightarrow k = 0$.'],
    ['Factor Theorem test', 'Exercise 2.3 Q2 (Page 29)', 'Show that $x - 2$ is a factor of $P(x) = x^3 - 4x^2 + x + 6$ and factorise $P(x)$ completely:', '$(x - 2)(x - 3)(x + 1)$', '$(x - 2)(x + 3)(x - 1)$', '$(x - 2)(x - 6)(x + 1)$', '$(x + 2)(x - 3)(x + 1)$'],
    ['Solving cubic equation by Factor Theorem', 'Exercise 2.3 Q5 (Page 30)', 'Solve the cubic equation $x^3 - 6x^2 + 11x - 6 = 0$ completely:', '$x = 1,\\; 2,\\; 3$', '$x = -1,\\; -2,\\; -3$', '$x = 1,\\; -2,\\; 3$', '$x = 1,\\; 2,\\; 6$', '$P(1) = 0 \\Rightarrow (x - 1)(x^2 - 5x + 6) = (x - 1)(x - 2)(x - 3) = 0$.'],
    ['Finding two unknowns p and q using Factor Theorem', 'Exercise 2.3 Q8 (Page 30)', 'Given that $x - 1$ and $x + 2$ are both factors of $f(x) = x^3 + px^2 + qx + 6$, find the values of $p$ and $q$:', '$p = -2,\\; q = -5$', '$p = 2,\\; q = -5$', '$p = -2,\\; q = 5$', '$p = 1,\\; q = -8$', '$f(1) = 1 + p + q + 6 = 0 \\Rightarrow p + q = -7$; $f(-2) = -8 + 4p - 2q + 6 = 0 \\Rightarrow 2p - q = 1 \\Rightarrow 3p = -6 \\Rightarrow p = -2, q = -5$.'],
    ['Quotient and remainder of polynomial division', 'Exercise 2.2 Q10 (Page 27)', 'Find the quotient $Q(x)$ and remainder $R$ when $x^3 - 3x^2 + 5x - 4$ is divided by $x - 1$:', '$Q(x) = x^2 - 2x + 3$ and $R = -1$', '$Q(x) = x^2 - 4x + 1$ and $R = -1$', '$Q(x) = x^2 - 2x + 3$ and $R = 1$', '$Q(x) = x^2 + 2x + 3$ and $R = -1$'],
    ['Root one is twice the other condition', 'Revision Exercise 2 Q4 (Page 32)', 'Find the positive value of $k$ if one root of $x^2 - 9x + k = 0$ is **twice** the other root:', '$k = 18$', '$k = 20$', '$k = 9$', '$k = 27$', 'Let roots be $\\alpha$ and $2\\alpha$: $3\\alpha = 9 \\Rightarrow \\alpha = 3$, so $k = \\alpha(2\\alpha) = 3(6) = 18$.'],
    ['Symmetric expression alpha/beta + beta/alpha', 'Revision Exercise 2 Q7 (Page 33)', 'If $\\alpha$ and $\\beta$ are the roots of $2x^2 - 6x + 1 = 0$, find the value of $\\frac{\\alpha}{\\beta} + \\frac{\\beta}{\\alpha}$:', '$16$', '$18$', '$17$', '$8$', '$\\alpha + \\beta = 3$ and $\\alpha\\beta = \\frac{1}{2}$. Then $\\frac{\\alpha^2 + \\beta^2}{\\alpha\\beta} = \\frac{9 - 1}{1/2} = 16$.'],
    ['Polynomial with known remainders', 'Revision Exercise 2 Q10 (Page 33)', 'A polynomial $P(x)$ leaves remainder $5$ when divided by $x - 1$ and remainder $11$ when divided by $x - 3$. If the remainder when $P(x)$ is divided by $(x - 1)(x - 3)$ is $ax + b$, find $a$ and $b$:', '$a = 3,\\; b = 2$ (Remainder $= 3x + 2$)', '$a = 2,\\; b = 3$ (Remainder $= 2x + 3$)', '$a = 3,\\; b = -2$ (Remainder $= 3x - 2$)', '$a = 6,\\; b = -1$'],
  ]);

  pushDistinctChapterBank('addmath-f3-bank-ch3', 'Form 3', 'Additional Mathematics', 'Chapter 3: Functions', ADD_MATH_F3_BOOK, [
    ['Domain of rational function with linear denominator', 'Exercise 3.1 Q2 (Page 37)', 'Find the domain and range of the rational function $f(x) = \\frac{3x + 2}{x - 4}$:', 'Domain: $\\{x \\in \\mathbb{R} : x \\ne 4\\}$ ; Range: $\\{y \\in \\mathbb{R} : y \\ne 3\\}$', 'Domain: $\\{x \\in \\mathbb{R} : x \\ne -4\\}$ ; Range: $\\{y \\in \\mathbb{R} : y \\ne -3\\}$', 'Domain: $\\mathbb{R}$ ; Range: $\\{y \\in \\mathbb{R} : y \\ne 4\\}$', 'Domain: $\\{x \\in \\mathbb{R} : x \\ne 4\\}$ ; Range: $\\{y \\in \\mathbb{R} : y \\ne -\\frac{2}{3}\\}$'],
    ['Vertical and horizontal asymptotes of quadratic rational function', 'Exercise 3.4 Q3 (Page 51)', 'State the vertical and horizontal asymptotes of $f(x) = \\frac{4x^2 - 9}{x^2 - 5x + 6}$:', 'Vertical asymptotes: $x = 2,\\; x = 3$ ; Horizontal asymptote: $y = 4$', 'Vertical asymptotes: $x = -2,\\; x = -3$ ; Horizontal asymptote: $y = 4$', 'Vertical asymptotes: $x = 2,\\; x = 3$ ; Horizontal asymptote: $y = 0$', 'Vertical asymptotes: $x = \\pm\\frac{3}{2}$ ; Horizontal asymptote: $y = 1$'],
    ['Horizontal asymptote when degree of numerator is smaller', 'Exercise 3.4 Q5 (Page 51)', 'Find the vertical and horizontal asymptotes of the rational function $g(x) = \\frac{5x + 1}{x^2 - 9}$:', 'Vertical: $x = -3,\\; x = 3$ ; Horizontal: $y = 0$', 'Vertical: $x = 9$ ; Horizontal: $y = 5$', 'Vertical: $x = -3,\\; x = 3$ ; Horizontal: $y = 5$', 'Vertical: $x = 3$ only ; Horizontal: $y = 0$'],
    ['Oblique (slant) asymptote of rational function', 'Exercise 3.4 Q8 (Page 52)', 'Find the vertical asymptote and oblique (slant) asymptote of $f(x) = \\frac{x^2 + 3x + 5}{x + 1}$:', 'Vertical: $x = -1$ ; Oblique: $y = x + 2$', 'Vertical: $x = 1$ ; Oblique: $y = x + 4$', 'Vertical: $x = -1$ ; Oblique: $y = x + 3$', 'Vertical: $x = -1$ ; Horizontal: $y = 1$', 'By polynomial division, $\\frac{x^2 + 3x + 5}{x + 1} = x + 2 + \\frac{3}{x + 1}$, so $y = x + 2$ is the oblique asymptote.'],
    ['Inverse of a rational function', 'Exercise 3.2 Q4 (Page 42)', 'Given $f(x) = \\frac{2x + 3}{x - 1}$ for $x \\ne 1$, find its inverse function $f^{-1}(x)$ and state the domain of $f^{-1}$:', '$f^{-1}(x) = \\frac{x + 3}{x - 2}$ for $x \\ne 2$', '$f^{-1}(x) = \\frac{x - 3}{x + 2}$ for $x \\ne -2$', '$f^{-1}(x) = \\frac{x - 1}{2x + 3}$ for $x \\ne -\\frac{3}{2}$', '$f^{-1}(x) = \\frac{2x - 1}{x + 3}$ for $x \\ne -3$'],
    ['Composite function fg(x) and gf(x)', 'Exercise 3.3 Q2 (Page 46)', 'Given $f(x) = 2x - 3$ and $g(x) = x^2 + 1$, find the composite functions $(f \\circ g)(x)$ and $(g \\circ f)(x)$:', '$(f \\circ g)(x) = 2x^2 - 1$ and $(g \\circ f)(x) = 4x^2 - 12x + 10$', '$(f \\circ g)(x) = 4x^2 - 12x + 10$ and $(g \\circ f)(x) = 2x^2 - 1$', '$(f \\circ g)(x) = 2x^2 + 2$ and $(g \\circ f)(x) = 4x^2 - 8$', '$(f \\circ g)(x) = 2x^3 - 3x^2 + 2x - 3$'],
    ['Evaluating composite inverse (fg)^-1', 'Exercise 3.3 Q6 (Page 47)', 'If $f(x) = 3x + 2$ and $g(x) = x - 4$, find $(f \\circ g)(x)$ and $(f \\circ g)^{-1}(10)$:', '$(f \\circ g)(x) = 3x - 10$ and $(f \\circ g)^{-1}(10) = \\frac{20}{3}$', '$(f \\circ g)(x) = 3x - 2$ and $(f \\circ g)^{-1}(10) = 4$', '$(f \\circ g)(x) = 3x + 6$ and $(f \\circ g)^{-1}(10) = \\frac{4}{3}$', '$(f \\circ g)(x) = 3x - 10$ and $(f \\circ g)^{-1}(10) = 20$'],
    ['Absolute value / modulus function equation', 'Exercise 3.5 Q3 (Page 56)', 'Solve the modulus equation $|2x - 5| = 9$ and state the minimum value of $h(x) = |2x - 5| - 3$:', '$x = 7$ or $x = -2$ ; Minimum value $= -3$', '$x = 7$ only ; Minimum value $= 0$', '$x = -7$ or $x = 2$ ; Minimum value $= -3$', '$x = 7$ or $x = -2$ ; Minimum value $= -5$'],
    ['Domain of square root function', 'Exercise 3.1 Q6 (Page 38)', 'Find the natural domain in $\\mathbb{R}$ of the function $f(x) = \\sqrt{12 - 3x}$:', '$\\{x \\in \\mathbb{R} : x \\le 4\\}$ (or $(-\\infty, 4]$)', '$\\{x \\in \\mathbb{R} : x \\ge 4\\}$', '$\\{x \\in \\mathbb{R} : x < 4\\}$', '$\\{x \\in \\mathbb{R} : -4 \\le x \\le 4\\}$'],
    ['Piecewise function evaluation', 'Exercise 3.5 Q6 (Page 57)', 'A piecewise function is defined by $f(x) = \\begin{cases} x^2 + 1, & x < 2 \\\\ 3x - 1, & x \\ge 2 \\end{cases}$. Evaluate $f(-1) + f(2) + f(4)$:', '$18$', '$20$', '$16$', '$24$', '$f(-1) = (-1)^2 + 1 = 2$; $f(2) = 3(2) - 1 = 5$; $f(4) = 3(4) - 1 = 11 \\Rightarrow 2 + 5 + 11 = 18$.'],
    ['Self-inverse rational function', 'Exercise 3.2 Q8 (Page 43)', 'Show that $f(x) = \\frac{x + 5}{x - 1}$ ($x \\ne 1$) is a **self-inverse** function and find $(f \\circ f)(7)$:', '$f^{-1}(x) = \\frac{x + 5}{x - 1} = f(x)$ and $(f \\circ f)(7) = 7$', '$f^{-1}(x) = \\frac{x - 5}{x + 1}$ and $(f \\circ f)(7) = 2$', '$f^{-1}(x) = f(x)$ and $(f \\circ f)(7) = 1$', '$f^{-1}(x) = \\frac{x + 1}{x - 5}$ and $(f \\circ f)(7) = 7$'],
    ['Intercepts of a rational function graph', 'Exercise 3.4 Q6 (Page 52)', 'Find the $x$-intercept and $y$-intercept of the rational function $y = \\frac{2x - 6}{x + 3}$:', '$x$-intercept: $(3, 0)$ ; $y$-intercept: $(0, -2)$', '$x$-intercept: $(-3, 0)$ ; $y$-intercept: $(0, 2)$', '$x$-intercept: $(6, 0)$ ; $y$-intercept: $(0, -2)$', '$x$-intercept: $(3, 0)$ ; $y$-intercept: $(0, 2)$'],
    ['One-to-one (injective) function test', 'Exercise 3.2 Q2 (Page 41)', 'Why does $f(x) = x^2 - 4$ defined on all $x \\in \\mathbb{R}$ fail to have an inverse function unless its domain is restricted to $x \\ge 0$?', 'Because $f(x)$ is many-to-one on $\\mathbb{R}$ (e.g., $f(-2) = f(2) = 0$) and fails the horizontal line test', 'Because $x^2 - 4$ has a vertical asymptote', 'Because quadratic functions are not continuous', 'Because $f(0) = -4$ is negative'],
    ['Range of quadratic function on restricted domain', 'Revision Exercise 3 Q4 (Page 60)', 'Find the vertex and range of $f(x) = -x^2 + 4x + 5$ for $x \\in \\mathbb{R}$:', 'Vertex $(2, 9)$ (Maximum) ; Range: $\\{y \\in \\mathbb{R} : y \\le 9\\}$', 'Vertex $(2, 9)$ (Minimum) ; Range: $\\{y \\in \\mathbb{R} : y \\ge 9\\}$', 'Vertex $(-2, 1)$ ; Range: $\\{y \\in \\mathbb{R} : y \\le 5\\}$', 'Vertex $(2, 5)$ ; Range: $\\{y \\in \\mathbb{R} : y \\le 5\\}$', '$-(x - 2)^2 + 9 \\le 9$, with maximum $9$ at $x = 2$.'],
    ['Hole (removable discontinuity) vs vertical asymptote', 'Revision Exercise 3 Q7 (Page 61)', 'For $f(x) = \\frac{x^2 - 4}{x - 2}$ ($x \\ne 2$), simplify $f(x)$ and state what occurs on the graph at $x = 2$:', '$f(x) = x + 2$ for $x \\ne 2$, with a removable hole at $(2, 4)$', 'A vertical asymptote at $x = 2$', '$f(x) = x - 2$ with a hole at $(2, 0)$', 'A horizontal asymptote at $y = 2$'],
    ['Solving functional equation f(g(x)) = k', 'Revision Exercise 3 Q10 (Page 61)', 'Given $f(x) = \\frac{12}{x + 1}$ and $g(x) = 2x - 1$, solve the equation $f(g(x)) = 3$:', '$x = 2$', '$x = 1.5$', '$x = 3$', '$x = 4$', '$f(g(x)) = \\frac{12}{2x} = \\frac{6}{x} = 3 \\Rightarrow x = 2$.'],
  ]);

  pushDistinctChapterBank('addmath-f3-bank-ch4', 'Form 3', 'Additional Mathematics', 'Chapter 4: Statistics', ADD_MATH_F3_BOOK, [
    ['Quartiles and semi-interquartile range from class interval table', 'Exercise 4.2 Q2 (Page 77)', 'Given the grouped frequency distribution table for $N = 40$ students: Class Interval: 10–19, 20–29, 30–39, 40–49, 50–59 | Frequency (f): 4, 8, 16, 8, 4. (a) Calculate the lower quartile $Q_1$ and upper quartile $Q_3$. (b) Find the interquartile range ($\\text{IQR}$) and semi-interquartile range ($\\text{SIR}$):', '(a) $Q_1 = 27.0,\\; Q_3 = 42.0$ ; (b) $\\text{IQR} = 15.0,\\; \\text{SIR} = 7.5$', '(a) $Q_1 = 24.5,\\; Q_3 = 44.5$ ; (b) $\\text{IQR} = 20.0,\\; \\text{SIR} = 10.0$', '(a) $Q_1 = 27.0,\\; Q_3 = 42.0$ ; (b) $\\text{IQR} = 7.5,\\; \\text{SIR} = 15.0$', '(a) $Q_1 = 22.0,\\; Q_3 = 40.0$ ; (b) $\\text{IQR} = 18.0,\\; \\text{SIR} = 9.0$', 'Cumulative frequencies are $4, 12, 28, 36, 40$. $Q_1 = 19.5 + \\left(\\frac{10 - 4}{8}\\right)\\times 10 = 27.0$; $Q_3 = 39.5 + \\left(\\frac{30 - 28}{8}\\right)\\times 10 = 42.0$. Thus $\\text{IQR} = 42.0 - 27.0 = 15.0$ and $\\text{SIR} = \\frac{15.0}{2} = 7.5$.'],
    ['Grouped interval table: Mean by assumed mean, median, and mode', 'Exercise 4.3 Q3 (Page 82)', 'The examination scores of $N = 50$ candidates are shown in the interval table: Class Interval: 20–29, 30–39, 40–49, 50–59, 60–69 | Frequency (f): 4, 10, 20, 10, 6. (a) Using assumed mean $A = 44.5$, find the arithmetic mean $\\bar{x}$. (b) Find the median and mode of the distribution:', '(a) $\\bar{x} = 45.3$ ; (b) Median $= 45.0$, Mode $= 44.5$', '(a) $\\bar{x} = 44.5$ ; (b) Median $= 44.5$, Mode $= 45.0$', '(a) $\\bar{x} = 46.5$ ; (b) Median $= 45.0$, Mode $= 45.5$', '(a) $\\bar{x} = 45.3$ ; (b) Median $= 46.0$, Mode $= 44.5$', 'With $A = 44.5$, $\\sum fd = 4(-20)+10(-10)+20(0)+10(10)+6(20) = 40 \\Rightarrow \\bar{x} = 44.5 + \\frac{40}{50} = 45.3$. Median class is $40\\text{–}49$ ($f_b = 14, f_m = 20$): $\\text{Median} = 39.5 + \\left(\\frac{25 - 14}{20}\\right)\\times 10 = 45.0$. Modal class is $40\\text{–}49$ ($\\Delta_1 = 10, \\Delta_2 = 10$): $\\text{Mode} = 39.5 + \\left(\\frac{10}{10 + 10}\\right)\\times 10 = 44.5$.'],
    ['Variance and standard deviation from grouped class interval table', 'Exercise 4.5 Q5 (Page 93)', 'Given the grouped frequency distribution table: Class Interval: 10–14, 15–19, 20–24, 25–29, 30–34 | Frequency (f): 4, 8, 16, 8, 4. (a) Find the mean $\\bar{x}$ using class marks $x$. (b) Calculate the variance $\\sigma^2$ and standard deviation $\\sigma$ (to $2$ d.p.):', '(a) $\\bar{x} = 22$ ; (b) $\\sigma^2 = 30$ and $\\sigma = \\sqrt{30} \\approx 5.48$', '(a) $\\bar{x} = 22$ ; (b) $\\sigma^2 = 25$ and $\\sigma = 5.00$', '(a) $\\bar{x} = 20$ ; (b) $\\sigma^2 = 30$ and $\\sigma \\approx 5.48$', '(a) $\\bar{x} = 22$ ; (b) $\\sigma^2 = 15$ and $\\sigma \\approx 3.87$', 'Class marks are $x = 12, 17, 22, 27, 32$ and $N = 40$. By symmetry $\\bar{x} = 22$. $\\sum f(x - \\bar{x})^2 = 4(100) + 8(25) + 16(0) + 8(25) + 4(100) = 1200 \\Rightarrow \\sigma^2 = \\frac{1200}{40} = 30$ and $\\sigma = \\sqrt{30} \\approx 5.48$.'],
    ['Mean absolute deviation (MAD) from grouped interval table', 'Exercise 4.4 Q4 (Page 88)', 'Given the grouped distribution of plant heights (in cm): Class Interval: 1–5, 6–10, 11–15, 16–20, 21–25 | Frequency (f): 2, 4, 8, 4, 2. (a) Find the mean height $\\bar{x}$. (b) Calculate the Mean Absolute Deviation ($\\text{MAD} = \\frac{\\sum f|x - \\bar{x}|}{\\sum f}$):', '(a) $\\bar{x} = 13\\text{ cm}$ ; (b) $\\text{MAD} = 4.0\\text{ cm}$', '(a) $\\bar{x} = 13\\text{ cm}$ ; (b) $\\text{MAD} = 5.0\\text{ cm}$', '(a) $\\bar{x} = 12.5\\text{ cm}$ ; (b) $\\text{MAD} = 4.0\\text{ cm}$', '(a) $\\bar{x} = 13\\text{ cm}$ ; (b) $\\text{MAD} = 3.5\\text{ cm}$', 'Class marks are $3, 8, 13, 18, 23$ with $N = 20$ and $\\bar{x} = 13\\text{ cm}$. $\\sum f|x - 13| = 2(10) + 4(5) + 8(0) + 4(5) + 2(10) = 80 \\Rightarrow \\text{MAD} = \\frac{80}{20} = 4.0\\text{ cm}$.'],
    ['Coding method for standard deviation of grouped interval table', 'Exercise 4.6 Q3 (Page 96)', 'For the grouped distribution of $N = 50$ scores: Class Interval: 40–49, 50–59, 60–69, 70–79, 80–89 | Frequency (f): 6, 10, 18, 10, 6. (a) Using assumed mean $A = 64.5$ and coded unit $u = \\frac{x - 64.5}{10}$, find $\\sum fu$ and $\\sum fu^2$. (b) Find the mean $\\bar{x}$, variance $\\sigma^2$, and standard deviation $\\sigma$:', '(a) $\\sum fu = 0,\\; \\sum fu^2 = 68$ ; (b) $\\bar{x} = 64.5,\\; \\sigma^2 = 136,\\; \\sigma \\approx 11.66$', '(a) $\\sum fu = 0,\\; \\sum fu^2 = 68$ ; (b) $\\bar{x} = 64.5,\\; \\sigma^2 = 68,\\; \\sigma \\approx 8.25$', '(a) $\\sum fu = 10,\\; \\sum fu^2 = 68$ ; (b) $\\bar{x} = 66.5,\\; \\sigma^2 = 136,\\; \\sigma \\approx 11.66$', '(a) $\\sum fu = 0,\\; \\sum fu^2 = 50$ ; (b) $\\bar{x} = 64.5,\\; \\sigma^2 = 100,\\; \\sigma = 10.00$', 'Here $u = -2, -1, 0, 1, 2 \\Rightarrow \\sum fu = 0$ and $\\sum fu^2 = 6(4) + 10(1) + 0 + 10(1) + 6(4) = 68$. Thus $\\bar{x} = 64.5$, $\\sigma^2 = 10^2\\left(\\frac{68}{50} - 0\\right) = 136$, and $\\sigma = \\sqrt{136} \\approx 11.66$.'],
    ['Missing frequency in a grouped class interval table', 'Revision Exercise 4 Q2 (Page 98)', 'In the grouped frequency table: Class Interval: 1–10, 11–20, 21–30, 31–40, 41–50 | Frequency (f): 3, 7, y, 7, 3, the median is $25.5$ and the total number of observations is $N = 30$. (a) Find the missing frequency $y$. (b) Calculate the quartile deviation (semi-interquartile range):', '(a) $y = 10$ ; (b) $Q_1 = 17.07,\\; Q_3 = 33.93,\\; \\text{SIR} = 8.43$', '(a) $y = 8$ ; (b) $Q_1 = 15.5,\\; Q_3 = 35.5,\\; \\text{SIR} = 10.0$', '(a) $y = 10$ ; (b) $Q_1 = 15.5,\\; Q_3 = 35.5,\\; \\text{SIR} = 10.0$', '(a) $y = 12$ ; (b) $Q_1 = 17.07,\\; Q_3 = 33.93,\\; \\text{SIR} = 8.43$', '(a) $3 + 7 + y + 7 + 3 = 30 \\Rightarrow y = 10$. (b) $Q_1$ ($\\frac{30}{4} = 7.5$, in $11\\text{–}20$): $Q_1 = 10.5 + \\frac{7.5 - 3}{7}\\times 10 = 17.07$; $Q_3$ ($22.5$, in $31\\text{–}40$): $Q_3 = 30.5 + \\frac{22.5 - 20}{7}\\times 10 = 33.93 \\Rightarrow \\text{SIR} = \\frac{33.93 - 17.07}{2} = 8.43$.'],
    ['Ungrouped mean, median, and mode', 'Exercise 4.1 Q1 (Page 68)', 'For the dataset $4, 7, 9, 7, 11, 13, 12$, find the mode, median, and arithmetic mean $\\bar{x}$:', 'Mode $= 7$, Median $= 9$, Mean $= 9$', 'Mode $= 7$, Median $= 7$, Mean $= 9$', 'Mode $= 9$, Median $= 9$, Mean $= 8.5$', 'Mode $= 7$, Median $= 9$, Mean $= 10$'],
    ['Quartiles and interquartile range of ungrouped data', 'Exercise 4.1 Q4 (Page 70)', 'For the ordered observations $6, 8, 11, 14, 17, 20, 24$, find the lower quartile $Q_1$, median $Q_2$, upper quartile $Q_3$, and interquartile range ($\\text{IQR}$):', '$Q_1 = 8,\\; Q_2 = 14,\\; Q_3 = 20,\\; \\text{IQR} = 12$', '$Q_1 = 9.5,\\; Q_2 = 14,\\; Q_3 = 18.5,\\; \\text{IQR} = 9$', '$Q_1 = 8,\\; Q_2 = 14,\\; Q_3 = 20,\\; \\text{IQR} = 6$', '$Q_1 = 6,\\; Q_2 = 14,\\; Q_3 = 24,\\; \\text{IQR} = 18$'],
    ['Grouped data median formula', 'Exercise 4.3 Q2 (Page 81)', 'In a grouped frequency distribution of $N = 60$ students: Class Interval: 20–29, 30–39, 40–49, 50–59, 60–69 | Frequency (f): 8, 13, 15, 14, 10, the median class is $40\\text{–}49$ (boundaries $39.5\\text{–}49.5$, width $c = 10$, $f_m = 15$, $f_b = 21$). Calculate the median:', '$45.5$', '$46.0$', '$44.5$', '$43.5$', '$\\text{Median} = L + \\left(\\frac{N/2 - f_b}{f_m}\\right)c = 39.5 + \\left(\\frac{30 - 21}{15}\\right)\\times 10 = 39.5 + 6 = 45.5$.'],
    ['Grouped data mode formula', 'Exercise 4.3 Q5 (Page 82)', 'In the grouped distribution: Class Interval: 30–39, 40–49, 50–59, 60–69, 70–79 | Frequency (f): 8, 16, 24, 12, 5, the modal class is $50\\text{–}59$ ($L = 49.5$, width $c = 10$, $f_1 = 24, f_0 = 16, f_2 = 12$). Calculate the mode:', '$53.5$', '$54.5$', '$52.5$', '$55.0$', '$\\Delta_1 = 24 - 16 = 8$, $\\Delta_2 = 24 - 12 = 12 \\Rightarrow \\text{Mode} = 49.5 + \\left(\\frac{8}{8 + 12}\\right)\\times 10 = 49.5 + 4 = 53.5$.'],
    ['Computational formula for variance', 'Exercise 4.5 Q4 (Page 93)', 'For $n = 10$ observations, $\\sum x = 70$ and $\\sum x^2 = 580$. Calculate the mean $\\bar{x}$, variance $\\sigma^2$, and standard deviation $\\sigma$:', '$\\bar{x} = 7,\\; \\sigma^2 = 9,\\; \\sigma = 3$', '$\\bar{x} = 7,\\; \\sigma^2 = 58,\\; \\sigma = 7.62$', '$\\bar{x} = 7,\\; \\sigma^2 = 81,\\; \\sigma = 9$', '$\\bar{x} = 70,\\; \\sigma^2 = 9,\\; \\sigma = 3$', '$\\bar{x} = \\frac{70}{10} = 7$, and $\\sigma^2 = \\frac{\\sum x^2}{n} - \\bar{x}^2 = \\frac{580}{10} - 49 = 58 - 49 = 9 \\Rightarrow \\sigma = 3$.'],
    ['Effect of adding a constant on mean and SD', 'Exercise 4.5 Q7 (Page 94)', 'A dataset has mean $\\bar{x} = 24$ and standard deviation $\\sigma = 5$. If $10$ is added to every observation ($y = x + 10$), what are the new mean and new standard deviation?', 'New mean $= 34$, New standard deviation $= 5$', 'New mean $= 34$, New standard deviation $= 15$', 'New mean $= 24$, New standard deviation $= 15$', 'New mean $= 34$, New standard deviation $= 25$'],
    ['Effect of scaling on mean and variance', 'Exercise 4.5 Q8 (Page 94)', 'A dataset has mean $\\bar{x} = 15$ and variance $\\sigma^2 = 4$ ($\\sigma = 2$). If every value is multiplied by $3$ ($y = 3x$), find the new mean, new standard deviation, and new variance:', 'Mean $= 45$, $\\sigma_y = 6$, Variance $\\sigma_y^2 = 36$', 'Mean $= 45$, $\\sigma_y = 6$, Variance $\\sigma_y^2 = 12$', 'Mean $= 45$, $\\sigma_y = 2$, Variance $\\sigma_y^2 = 4$', 'Mean $= 18$, $\\sigma_y = 6$, Variance $\\sigma_y^2 = 36$'],
    ['Combined mean of two groups', 'Exercise 4.2 Q6 (Page 77)', 'Stream A has $20$ students with a mean score of $65$, and Stream B has $30$ students with a mean score of $75$. Find the combined mean score of all $50$ students:', '$71$', '$70$', '$72$', '$69$', '$\\bar{x} = \\frac{20(65) + 30(75)}{20 + 30} = \\frac{1300 + 2250}{50} = \\frac{3550}{50} = 71$.'],
    ['Percentiles and deciles from ogive', 'Revision Exercise 4 Q7 (Page 99)', 'On a cumulative frequency curve (ogive) for $N = 200$ candidates, which cumulative frequency values correspond to the $25\\text{th}$ percentile ($P_{25}$), the $7\\text{th}$ decile ($D_7$), and the $90\\text{th}$ percentile ($P_{90}$)?', '$50,\\; 140,\\text{ and } 180$', '$25,\\; 70,\\text{ and } 90$', '$50,\\; 70,\\text{ and } 180$', '$25,\\; 140,\\text{ and } 180$'],
    ['Corrected mean after data entry error', 'Revision Exercise 4 Q10 (Page 100)', 'The mean mark of $40$ students was calculated as $62$. Later it was discovered that a score of $78$ was misread as $38$. Find the correct mean mark:', '$63$', '$61$', '$64$', '$62.5$', 'Corrected sum $= 40(62) - 38 + 78 = 2480 + 40 = 2520 \\Rightarrow \\text{Mean} = \\frac{2520}{40} = 63$.'],
  ]);

  pushDistinctChapterBank('addmath-f3-bank-ch5', 'Form 3', 'Additional Mathematics', 'Chapter 5: Trigonometry', ADD_MATH_F3_BOOK, [
    ['Pythagorean identity sec^2 and tan^2', 'Exercise 5.1 Q2 (Page 108)', 'Simplify the trigonometric expression $\\frac{\\sec^2\\theta - 1}{\\sec^2\\theta}$ and state its equivalent single ratio:', '$\\sin^2\\theta$', '$\\cos^2\\theta$', '$\\tan^2\\theta$', '$\\cot^2\\theta$', '$\\frac{\\tan^2\\theta}{\\sec^2\\theta} = \\frac{\\sin^2\\theta/\\cos^2\\theta}{1/\\cos^2\\theta} = \\sin^2\\theta$.'],
    ['Eliminating parameter theta from ellipse equations', 'Exercise 5.1 Q6 (Page 109)', 'Eliminate $\\theta$ from the parametric equations $x = 4\\cos\\theta$ and $y = 3\\sin\\theta$:', '$\\frac{x^2}{16} + \\frac{y^2}{9} = 1$ (or $9x^2 + 16y^2 = 144$)', '$\\frac{x^2}{4} + \\frac{y^2}{3} = 1$', '$16x^2 + 9y^2 = 144$', '$\\frac{x^2}{16} - \\frac{y^2}{9} = 1$'],
    ['Eliminating theta using sec and tan', 'Exercise 5.1 Q9 (Page 109)', 'Eliminate $\\theta$ from $x = 2\\sec\\theta$ and $y = 5\\tan\\theta$:', '$\\frac{x^2}{4} - \\frac{y^2}{25} = 1$ (or $25x^2 - 4y^2 = 100$)', '$\\frac{x^2}{4} + \\frac{y^2}{25} = 1$', '$\\frac{y^2}{25} - \\frac{x^2}{4} = 1$', '$4x^2 - 25y^2 = 100$'],
    ['Signs of trig ratios in quadrants (ASTC)', 'Exercise 5.2 Q3 (Page 112)', 'Given that $\\sin\\theta = -\\frac{3}{5}$ and $\\theta$ lies in the third quadrant ($180^\\circ < \\theta < 270^\\circ$), find $\\cos\\theta$ and $\\tan\\theta$:', '$\\cos\\theta = -\\frac{4}{5}$ and $\\tan\\theta = \\frac{3}{4}$', '$\\cos\\theta = \\frac{4}{5}$ and $\\tan\\theta = -\\frac{3}{4}$', '$\\cos\\theta = -\\frac{4}{5}$ and $\\tan\\theta = -\\frac{3}{4}$', '$\\cos\\theta = -\\frac{3}{4}$ and $\\tan\\theta = \\frac{4}{5}$'],
    ['Compound angle formula for sin(A + B) and cos(A - B)', 'Exercise 5.3 Q2 (Page 115)', 'Using $\\sin(45^\\circ + 30^\\circ)$, find the exact surd value of $\\sin 75^\\circ$:', '$\\frac{\\sqrt{6} + \\sqrt{2}}{4}$', '$\\frac{\\sqrt{6} - \\sqrt{2}}{4}$', '$\\frac{\\sqrt{3} + 1}{2}$', '$\\frac{\\sqrt{3} + \\sqrt{2}}{4}$'],
    ['Compound angle formula for tan(A + B)', 'Exercise 5.3 Q5 (Page 116)', 'Given that $\\tan A = \\frac{1}{2}$ and $\\tan B = \\frac{1}{3}$ for acute angles $A$ and $B$, evaluate $\\tan(A + B)$ and find $A + B$:', '$\\tan(A + B) = 1 \\Rightarrow A + B = 45^\\circ$', '$\\tan(A + B) = \\frac{5}{6} \\Rightarrow A + B = 60^\\circ$', '$\\tan(A + B) = \\frac{5}{7} \\Rightarrow A + B = 30^\\circ$', '$\\tan(A + B) = 1 \\Rightarrow A + B = 60^\\circ$', '$\\tan(A+B) = \\frac{1/2 + 1/3}{1 - (1/2)(1/3)} = \\frac{5/6}{5/6} = 1 \\Rightarrow A + B = 45^\\circ$.'],
    ['Double angle formulae sin 2A, cos 2A, tan 2A', 'Exercise 5.4 Q2 (Page 119)', 'If $\\sin\\theta = \\frac{5}{13}$ and $\\theta$ is acute, find the exact values of $\\sin 2\\theta$ and $\\cos 2\\theta$:', '$\\sin 2\\theta = \\frac{120}{169}$ and $\\cos 2\\theta = \\frac{119}{169}$', '$\\sin 2\\theta = \\frac{60}{169}$ and $\\cos 2\\theta = \\frac{119}{169}$', '$\\sin 2\\theta = \\frac{120}{169}$ and $\\cos 2\\theta = -\\frac{119}{169}$', '$\\sin 2\\theta = \\frac{10}{26}$ and $\\cos 2\\theta = \\frac{24}{26}$'],
    ['Double angle identity simplification', 'Exercise 5.4 Q6 (Page 120)', 'Simplify the trigonometric expression $\\frac{\\sin 2\\theta}{1 + \\cos 2\\theta}$:', '$\\tan\\theta$', '$\\cot\\theta$', '$\\sin\\theta$', '$2\\tan\\theta$', '$\\frac{2\\sin\\theta\\cos\\theta}{2\\cos^2\\theta} = \\tan\\theta$.'],
    ['Sine rule in a scalene triangle', 'Exercise 5.5 Q2 (Page 124)', 'In $\\triangle ABC$, $\\angle A = 30^\\circ$, $\\angle B = 45^\\circ$, and side $a = 10\\text{ cm}$. Using the Sine Rule, find the exact length of side $b$:', '$10\\sqrt{2}\\text{ cm}$', '$5\\sqrt{2}\\text{ cm}$', '$10\\sqrt{3}\\text{ cm}$', '$20\\text{ cm}$', '$\\frac{b}{\\sin 45^\\circ} = \\frac{10}{\\sin 30^\\circ} \\Rightarrow b = \\frac{10 \\times (\\sqrt{2}/2)}{1/2} = 10\\sqrt{2}\\text{ cm}$.'],
    ['Cosine rule for finding a side', 'Exercise 5.6 Q1 (Page 127)', 'In $\\triangle ABC$, $b = 8\\text{ cm}$, $c = 5\\text{ cm}$, and the included angle $\\angle A = 60^\\circ$. Using the Cosine Rule $a^2 = b^2 + c^2 - 2bc\\cos A$, find side $a$:', '$7\\text{ cm}$', '$\\sqrt{129}\\text{ cm}$', '$6\\text{ cm}$', '$9\\text{ cm}$', '$a^2 = 64 + 25 - 2(8)(5)(0.5) = 89 - 40 = 49 \\Rightarrow a = 7\\text{ cm}$.'],
    ['Cosine rule for finding largest angle', 'Exercise 5.6 Q4 (Page 128)', 'In $\\triangle PQR$ with sides $p = 3\\text{ cm}$, $q = 5\\text{ cm}$, and $r = 7\\text{ cm}$, find the largest interior angle $\\angle R$:', '$120^\\circ$', '$60^\\circ$', '$135^\\circ$', '$150^\\circ$', '$\\cos R = \\frac{3^2 + 5^2 - 7^2}{2(3)(5)} = \\frac{9 + 25 - 49}{30} = -\\frac{15}{30} = -\\frac{1}{2} \\Rightarrow \\angle R = 120^\\circ$.'],
    ['Area of triangle 1/2 ab sin C', 'Exercise 5.5 Q6 (Page 125)', 'Find the exact area of $\\triangle ABC$ given $a = 12\\text{ cm}$, $b = 10\\text{ cm}$, and included angle $\\angle C = 30^\\circ$:', '$30\\text{ cm}^2$', '$60\\text{ cm}^2$', '$30\\sqrt{3}\\text{ cm}^2$', '$20\\text{ cm}^2$', '$\\text{Area} = \\frac{1}{2}(12)(10)\\sin 30^\\circ = 60 \\times \\frac{1}{2} = 30\\text{ cm}^2$.'],
    ['Solving trigonometric equation on [0, 360]', 'Exercise 5.7 Q3 (Page 131)', 'Solve the trigonometric equation $2\\sin^2\\theta - \\sin\\theta - 1 = 0$ for $0^\\circ \\le \\theta \\le 360^\\circ$:', '$\\theta = 90^\\circ,\\; 210^\\circ,\\; 330^\\circ$', '$\\theta = 30^\\circ,\\; 150^\\circ,\\; 270^\\circ$', '$\\theta = 90^\\circ,\\; 150^\\circ,\\; 330^\\circ$', '$\\theta = 60^\\circ,\\; 210^\\circ,\\; 300^\\circ$', '$(2\\sin\\theta + 1)(\\sin\\theta - 1) = 0 \\Rightarrow \\sin\\theta = 1 (90^\\circ)$ or $\\sin\\theta = -\\frac{1}{2} (210^\\circ, 330^\\circ)$.'],
    ['Solving double-angle trig equation', 'Exercise 5.7 Q7 (Page 131)', 'Find all solutions in $0^\\circ \\le \\theta \\le 180^\\circ$ to the equation $\\sin 2\\theta = \\cos\\theta$:', '$\\theta = 30^\\circ,\\; 90^\\circ,\\; 150^\\circ$', '$\\theta = 30^\\circ,\\; 150^\\circ$ only', '$\\theta = 45^\\circ,\\; 90^\\circ,\\; 135^\\circ$', '$\\theta = 60^\\circ,\\; 90^\\circ,\\; 120^\\circ$', '$2\\sin\\theta\\cos\\theta - \\cos\\theta = \\cos\\theta(2\\sin\\theta - 1) = 0 \\Rightarrow \\cos\\theta = 0 (90^\\circ)$ or $\\sin\\theta = \\frac{1}{2} (30^\\circ, 150^\\circ)$.'],
    ['Proving fourth-power trig identity', 'Revision Exercise 5 Q4 (Page 133)', 'Simplify $\\cos^4\\theta - \\sin^4\\theta$ in terms of $\\cos 2\\theta$:', '$\\cos 2\\theta$', '$\\sin 2\\theta$', '$1$', '$\\cos^2 2\\theta$', '$(\\cos^2\\theta - \\sin^2\\theta)(\\cos^2\\theta + \\sin^2\\theta) = \\cos 2\\theta \\cdot 1 = \\cos 2\\theta$.'],
    ['Half-angle / t-formula substitution', 'Revision Exercise 5 Q9 (Page 134)', 'If $\\cos 2\\theta = \\frac{7}{25}$ and $\\theta$ is acute, use $\\cos 2\\theta = 1 - 2\\sin^2\\theta$ to find $\\sin\\theta$ and $\\cos\\theta$:', '$\\sin\\theta = \\frac{3}{5}$ and $\\cos\\theta = \\frac{4}{5}$', '$\\sin\\theta = \\frac{4}{5}$ and $\\cos\\theta = \\frac{3}{5}$', '$\\sin\\theta = \\frac{9}{25}$ and $\\cos\\theta = \\frac{16}{25}$', '$\\sin\\theta = \\frac{5}{13}$ and $\\cos\\theta = \\frac{12}{13}$'],
  ]);

  pushDistinctChapterBank('addmath-f3-bank-ch6', 'Form 3', 'Additional Mathematics', 'Chapter 6: Differentiation', ADD_MATH_F3_BOOK, [
    ['Derivative from first principles', 'Exercise 6.1 Q2 (Page 137)', 'Using the definition $f\'(x) = \\lim_{h \\to 0}\\frac{f(x+h) - f(x)}{h}$, find the derivative of $f(x) = 3x^2 - 4x$:', '$f\'(x) = 6x - 4$', '$f\'(x) = 3x - 4$', '$f\'(x) = 6x^2 - 4$', '$f\'(x) = 6x + 4$'],
    ['Power rule with fractional and negative exponents', 'Exercise 6.2 Q4 (Page 140)', 'Differentiate $y = 4\\sqrt{x} - \\frac{6}{x^2}$ with respect to $x$ ($x > 0$):', '$\\frac{dy}{dx} = \\frac{2}{\\sqrt{x}} + \\frac{12}{x^3}$', '$\\frac{dy}{dx} = \\frac{2}{\\sqrt{x}} - \\frac{12}{x^3}$', '$\\frac{dy}{dx} = 2\\sqrt{x} + \\frac{6}{x}$', '$\\frac{dy}{dx} = \\frac{4}{\\sqrt{x}} + \\frac{12}{x}$'],
    ['Chain rule (function of a function)', 'Exercise 6.3 Q3 (Page 144)', 'Find $\\frac{dy}{dx}$ if $y = (3x^2 - 5x + 1)^4$:', '$4(6x - 5)(3x^2 - 5x + 1)^3$', '$4(3x^2 - 5x + 1)^3$', '$(6x - 5)^4$', '$12x(3x^2 - 5x + 1)^3$'],
    ['Product rule of differentiation', 'Exercise 6.4 Q2 (Page 147)', 'Use the product rule to differentiate $y = (2x + 1)(x^2 - 3)$ and simplify:', '$\\frac{dy}{dx} = 6x^2 + 2x - 6$', '$\\frac{dy}{dx} = 4x$', '$\\frac{dy}{dx} = 6x^2 - 6$', '$\\frac{dy}{dx} = 2x^2 + 2x - 3$'],
    ['Quotient rule of differentiation', 'Exercise 6.5 Q3 (Page 150)', 'Differentiate $y = \\frac{2x - 1}{x + 3}$ with respect to $x$ using the quotient rule:', '$\\frac{dy}{dx} = \\frac{7}{(x + 3)^2}$', '$\\frac{dy}{dx} = \\frac{5}{(x + 3)^2}$', '$\\frac{dy}{dx} = \\frac{4x + 5}{(x + 3)^2}$', '$\\frac{dy}{dx} = 2$', '$\\frac{2(x + 3) - 1(2x - 1)}{(x + 3)^2} = \\frac{2x + 6 - 2x + 1}{(x + 3)^2} = \\frac{7}{(x + 3)^2}$.'],
    ['Implicit differentiation of a circle/conic', 'Exercise 6.6 Q4 (Page 154)', 'Find $\\frac{dy}{dx}$ by implicit differentiation for the curve $x^2 + y^2 - 4x + 6y = 12$:', '$\\frac{dy}{dx} = \\frac{2 - x}{y + 3}$', '$\\frac{dy}{dx} = -\\frac{x}{y}$', '$\\frac{dy}{dx} = \\frac{x - 2}{y + 3}$', '$\\frac{dy}{dx} = \\frac{2x - 4}{2y + 6}$'],
    ['Second derivative d2y/dx2', 'Exercise 6.7 Q2 (Page 157)', 'Given $y = 2x^4 - 5x^3 + 3x^2 - 7x + 4$, find the second derivative $\\frac{d^2y}{dx^2}$ at $x = 2$:', '$42$', '$36$', '$54$', '$18$', '$\\frac{dy}{dx} = 8x^3 - 15x^2 + 6x - 7 \\Rightarrow \\frac{d^2y}{dx^2} = 24x^2 - 30x + 6$. At $x = 2$: $24(4) - 60 + 6 = 42$.'],
    ['Derivatives of trigonometric functions', 'Exercise 6.8 Q3 (Page 161)', 'Differentiate $y = 3\\sin(2x) - 4\\cos(5x)$ with respect to $x$:', '$\\frac{dy}{dx} = 6\\cos(2x) + 20\\sin(5x)$', '$\\frac{dy}{dx} = 3\\cos(2x) + 4\\sin(5x)$', '$\\frac{dy}{dx} = 6\\cos(2x) - 20\\sin(5x)$', '$\\frac{dy}{dx} = -6\\cos(2x) + 20\\sin(5x)$'],
    ['Equations of tangent and normal to a curve', 'Exercise 6.9 Q2 (Page 165)', 'Find the equation of the tangent and normal to the curve $y = x^2 - 4x + 5$ at the point $(3, 2)$:', 'Tangent: $y = 2x - 4$ ; Normal: $x + 2y - 7 = 0$', 'Tangent: $y = 2x + 4$ ; Normal: $2x + y - 8 = 0$', 'Tangent: $y = -2x + 8$ ; Normal: $x - 2y + 1 = 0$', 'Tangent: $y = 2x - 4$ ; Normal: $x - 2y + 1 = 0$'],
    ['Stationary (turning) points and nature test', 'Exercise 6.10 Q3 (Page 169)', 'Find the coordinates and nature of the stationary points of the cubic curve $y = x^3 - 3x^2 - 9x + 5$:', 'Local maximum at $(-1, 10)$ and local minimum at $(3, -22)$', 'Local minimum at $(-1, 10)$ and local maximum at $(3, -22)$', 'Stationary points at $(1, -6)$ and $(-3, -22)$', 'Local maximum at $(0, 5)$ and local minimum at $(3, -22)$', '$\\frac{dy}{dx} = 3x^2 - 6x - 9 = 3(x + 1)(x - 3) = 0 \\Rightarrow x = -1, 3$. $\\frac{d^2y}{dx^2} = 6x - 6$: negative at $x = -1$ (max), positive at $x = 3$ (min).'],
    ['Maximum area of rectangular enclosure', 'Exercise 6.11 Q2 (Page 172)', 'A farmer has $80\\text{ m}$ of fencing to enclose a rectangular garden of area $A = x(40 - x)\\text{ m}^2$. Using differentiation, find the dimensions $x$ and $40 - x$ that maximize the area, and the maximum area:', '$20\\text{ m}$ by $20\\text{ m}$ ; Maximum area $= 400\\text{ m}^2$', '$25\\text{ m}$ by $15\\text{ m}$ ; Maximum area $= 375\\text{ m}^2$', '$30\\text{ m}$ by $10\\text{ m}$ ; Maximum area $= 300\\text{ m}^2$', '$40\\text{ m}$ by $20\\text{ m}$ ; Maximum area $= 800\\text{ m}^2$'],
    ['Kinematics displacement, velocity, acceleration', 'Exercise 6.12 Q3 (Page 175)', 'A particle moves along a straight line so that its displacement after $t$ seconds is $s(t) = t^3 - 6t^2 + 9t + 4\\text{ metres}$. Find its velocity $v(t)$, acceleration $a(t)$ at $t = 4\\text{ s}$, and the times when it is momentarily at rest:', '$v(4) = 9\\text{ m/s},\\; a(4) = 12\\text{ m/s}^2$ ; At rest at $t = 1\\text{ s}$ and $t = 3\\text{ s}$', '$v(4) = 0\\text{ m/s},\\; a(4) = 6\\text{ m/s}^2$ ; At rest at $t = 2\\text{ s}$', '$v(4) = 9\\text{ m/s},\\; a(4) = 24\\text{ m/s}^2$ ; At rest at $t = 1\\text{ s}$ and $t = 3\\text{ s}$', '$v(4) = 15\\text{ m/s},\\; a(4) = 12\\text{ m/s}^2$ ; At rest at $t = 3\\text{ s}$'],
    ['Related rates of change (expanding circle)', 'Exercise 6.13 Q2 (Page 178)', 'The radius $r$ of a circular ink blot is increasing at a constant rate of $\\frac{dr}{dt} = 0.5\\text{ cm/s}$. Find the rate at which its area $A = \\pi r^2$ is increasing ($\\frac{dA}{dt}$) when $r = 6\\text{ cm}$:', '$6\\pi\\text{ cm}^2/\\text{s}$', '$12\\pi\\text{ cm}^2/\\text{s}$', '$3\\pi\\text{ cm}^2/\\text{s}$', '$18\\pi\\text{ cm}^2/\\text{s}$', '$\\frac{dA}{dt} = \\frac{dA}{dr}\\cdot\\frac{dr}{dt} = 2\\pi r(0.5) = \\pi r$. At $r = 6$, $\\frac{dA}{dt} = 6\\pi\\text{ cm}^2/\\text{s}$.'],
    ['Small increments and approximations', 'Exercise 6.13 Q6 (Page 179)', 'Using $\\delta y \\approx \\frac{dy}{dx}\\,\\delta x$ with $y = \\sqrt{x}$, find an approximate value of $\\sqrt{101}$ given $\\sqrt{100} = 10$:', '$10.05$', '$10.10$', '$10.025$', '$10.01$', 'At $x = 100$ and $\\delta x = 1$: $\\delta y \\approx \\frac{1}{2\\sqrt{100}}(1) = 0.05 \\Rightarrow \\sqrt{101} \\approx 10 + 0.05 = 10.05$.'],
    ['Parametric differentiation dy/dx', 'Revision Exercise 6 Q5 (Page 182)', 'If $x = t^2$ and $y = t^3 - 3t$, find $\\frac{dy}{dx}$ in terms of $t$ and evaluate it at $t = 2$:', '$\\frac{dy}{dx} = \\frac{3t^2 - 3}{2t}$ ; Value at $t = 2$ is $\\frac{9}{4}$', '$\\frac{dy}{dx} = \\frac{2t}{3t^2 - 3}$ ; Value at $t = 2$ is $\\frac{4}{9}$', '$\\frac{dy}{dx} = 3t - 3$ ; Value at $t = 2$ is $3$', '$\\frac{dy}{dx} = \\frac{3t^2}{2t}$ ; Value at $t = 2$ is $3$'],
    ['Point of inflection of a cubic curve', 'Revision Exercise 6 Q8 (Page 183)', 'Find the coordinates of the point of inflection (where $\\frac{d^2y}{dx^2} = 0$) on the curve $y = x^3 - 6x^2 + 12x - 5$:', '$(2, 3)$', '$(2, -5)$', '$(0, -5)$', '$(1, 2)$', '$\\frac{dy}{dx} = 3x^2 - 12x + 12$ and $\\frac{d^2y}{dx^2} = 6x - 12 = 0 \\Rightarrow x = 2,\\; y = 8 - 24 + 24 - 5 = 3$.'],
  ]);

